type StepColor = "purple" | "green" | "orange" | "indigo";

/**
 * The source template coloured these four steps purple/green/orange/indigo.
 * Against the black-white-gold palette that reads as a leftover from the old
 * theme, so they're mapped onto a zinc ladder instead — the progression still
 * distinguishes the steps, and the gold accents stay the only colour on the
 * page. Keys keep their original names so the step data doesn't churn.
 */
const COLOR_CLASSES: Record<StepColor, string> = {
  purple: "bg-ink-deep",
  green: "bg-primary",
  orange: "bg-ink",
  indigo: "bg-ink-soft",
};

type Step = {
  step: string;
  title: string;
  description: string;
  image: string;
  color: StepColor;
  icon: ReactNode;
};

const STEPS: Step[] = [
  {
    step: "Step 01",
    title: "Pick your market",
    description: "Start with forex, crypto or metals — whichever fits your capital and schedule.",
    image: "/assets/imgs/home2/wp/wp-thumb1_1.webp",
    color: "purple",
    icon: ICON_COURSE,
  },
  {
    step: "Step 02",
    title: "Learn the strategy",
    description: "Chart reading, entries and exits, and the risk rules behind every setup.",
    image: "/assets/imgs/home2/wp/wp-thumb1_2.webp",
    color: "green",
    icon: ICON_PACE,
  },
  {
    step: "Step 03",
    title: "Trade live sessions",
    description: "Join weekly market sessions and place practice trades beside a mentor.",
    image: "/assets/imgs/home2/wp/wp-thumb1_3.webp",
    color: "orange",
    icon: ICON_PRACTICE,
  },
  {
    step: "Step 04",
    title: "Trade your own plan",
    description: "Leave with a written, tested plan and the discipline to follow it.",
    image: "/assets/imgs/home2/wp/wp-thumb1_4.webp",
    color: "indigo",
    icon: ICON_CERTIFICATE,
  },
];

/**
 * "How it works" steps section. The source template drives this as a
 * desktop-only hover/click accordion (three of four cards collapsed behind
 * negative margins and z-index stacking, background photo hidden until
 * hover/active) built for GSAP + a toggled "active" class. Per the brief to
 * render everything statically visible without added animation/interaction
 * complexity, this instead renders a plain, fully-visible responsive card
 * grid — preserving each step's color variant, icon, copy, and photo
 * faithfully, just without the collapse/expand choreography.
 */
export default function HowItWork2() {
  return (
    <section className="bg-bg py-16 lg:py-20 xl:py-[130px]">
      <div className="mx-auto w-full max-w-[1320px] px-4 sm:px-6 lg:px-8">
        <SectionHeading
          eyebrow="How it works"
          align="center"
          title={
            <>
              From first chart to live <em>desk</em>
            </>
          }
        />

        <Reveal
          stagger
          className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4 lg:gap-5"
        >
          {STEPS.map((item) => (
            <div
              key={item.step}
              className={`flex flex-col overflow-hidden rounded-[10px] transition-transform duration-300 hover:-translate-y-1 ${COLOR_CLASSES[item.color]}`}
            >
              <div className="hidden w-full overflow-hidden md:block md:aspect-[3/2]">
                <img
                  src={item.image}
                  alt="How It Work"
                  className="h-full w-full object-cover"
                />
              </div>
              <div className="flex flex-1 flex-col p-6">
                <div className="mb-6">{item.icon}</div>
                <span className="mb-[10px] inline-flex w-fit items-center rounded-full border border-white/30 px-[9px] py-1 text-sm font-medium capitalize text-white">
                  {item.step}
                </span>
                <h3 className="mb-[5px] text-xl font-medium leading-[120%] tracking-[-0.03em] text-white lg:text-2xl">
                  {item.title}
                </h3>
                <p className="max-w-[250px] text-sm leading-[160%] text-white lg:text-base">
                  {item.description}
                </p>
              </div>
            </div>
          ))}
        </Reveal>
      </div>
    </section>
  );
}
